// #6a993d794918a5e83bc3231b (#c3231b) треб.7 — блокировка входа в браузере после 5 неудач на 5 минут (кейс AUTH-LG-003).
// Решение пользователя 14.10: для пилота достаточно лимита Supabase 30/5 мин по IP + этой браузерной блокировки.
// spec: specs/auth-login.md (2.2, 2.3) · seed: tests/seed.spec.ts (гость).
// Ответы входа ПОДМЕНЕНЫ (400 / 429) — реальные попытки и лимит по IP не тратятся; данных не меняет — @prod-safe.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import {
  mockAuth, PASSWORD_LOGIN, INVALID_CREDENTIALS, OVER_RATE_LIMIT,
  LOCK_KEY, LOCK_MS, NONEXISTENT_EMAIL, WRONG_PASSWORD,
} from '../support/auth-mocks';

async function attempt(page: Page) {
  await page.getByRole('textbox', { name: 'מייל' }).fill(NONEXISTENT_EMAIL);
  await page.getByLabel('סיסמה', { exact: true }).fill(WRONG_PASSWORD);
  await page.getByRole('button', { name: 'כניסה', exact: true }).click();
}

const readLock = (page: Page) =>
  page.evaluate((k) => JSON.parse(localStorage.getItem(k) ?? 'null') as { failures: number; lockedUntil: number | null } | null, LOCK_KEY);

/** Плашка блокировки и неактивная кнопка с обратным отсчётом. */
async function expectLocked(page: Page) {
  const notice = page.getByTestId('login-rate-limited');
  await expect(notice).toBeVisible();
  await expect(notice).toContainText('יותר מדי ניסיונות כניסה');
  await expect(notice).toContainText('מטעמי אבטחה הכניסה נחסמה זמנית');
  const button = page.getByRole('button', { name: /^אפשר לנסות שוב בעוד [45]:\d\d$/ });
  await expect(button).toBeVisible();
  await expect(button).toBeDisabled();
}

test.describe('Вход — блокировка после 5 неудач (#6a993d794918a5e83bc3231b)', () => {
  test('гость: 5 неудач → «יותר מדי ניסיונות כניסה» на 5 мин, сохраняется после перезагрузки, снимается по истечении @desktop @prod-safe #6a993d794918a5e83bc3231b', async ({ page }) => {
    const login = await mockAuth(page, PASSWORD_LOGIN, { status: 400, body: INVALID_CREDENTIALS });
    await page.goto('/login');
    await expect(page.getByRole('heading', { level: 1, name: 'כניסה לחשבון' })).toBeVisible();

    // Попытки 1–4: обычная ошибка, кнопка активна.
    for (let i = 1; i <= 4; i++) {
      await attempt(page);
      await expect.poll(() => login.calls.length).toBe(i);
      await expect(page.getByTestId('login-error')).toContainText('המייל או הסיסמה שגויים');
      await expect(page.getByRole('button', { name: 'כניסה', exact: true })).toBeEnabled();
      expect((await readLock(page))?.failures).toBe(i);
    }

    // 5-я: блокировка на 5 минут (треб.7 «ניסיונות התחברות כושלים חוזרים מוגבלים בקצב»).
    const before = Date.now();
    await attempt(page);
    await expect.poll(() => login.calls.length).toBe(5);
    await expectLocked(page);
    const lock = await readLock(page);
    expect(lock?.failures).toBe(5);
    expect(lock?.lockedUntil ?? 0).toBeGreaterThanOrEqual(before + LOCK_MS - 5_000);
    expect(lock?.lockedUntil ?? 0).toBeLessThanOrEqual(Date.now() + LOCK_MS + 5_000);

    // 6-я попытка не уходит на сервер (кнопка неактивна, Enter в поле тоже не отправляет).
    await page.getByLabel('סיסמה', { exact: true }).press('Enter');
    await expect(page.getByTestId('login-rate-limited')).toBeVisible();
    expect(login.calls.length).toBe(5);

    // Перезагрузка — блокировка сохраняется.
    await page.reload();
    await expectLocked(page);

    // Имитация истечения 5 минут: lockedUntil в прошлом → после перезагрузки вход снова доступен.
    await page.evaluate((k) => localStorage.setItem(k, JSON.stringify({ failures: 5, lockedUntil: Date.now() - 1_000 })), LOCK_KEY);
    await page.reload();
    await expect(page.getByRole('button', { name: 'כניסה', exact: true })).toBeEnabled();
    await expect(page.getByTestId('login-rate-limited')).toHaveCount(0);
    expect(await readLock(page)).toBeNull();
  });

  test('гость: ответ сервера 429 (лимит по IP) → сразу «יותר מדי ניסיונות כניסה», кнопка заблокирована @desktop @prod-safe #6a993d794918a5e83bc3231b', async ({ page }) => {
    const login = await mockAuth(page, PASSWORD_LOGIN, { status: 429, body: OVER_RATE_LIMIT });
    await page.goto('/login');
    await attempt(page);
    await expect.poll(() => login.calls.length).toBe(1);
    await expectLocked(page);
    await expect(page.getByTestId('login-error')).toHaveCount(0);
    const lock = await readLock(page);
    expect(lock?.lockedUntil ?? 0).toBeGreaterThan(Date.now() + LOCK_MS - 10_000);

    // Очистка
    await page.evaluate((k) => localStorage.removeItem(k), LOCK_KEY);
  });
});
